def cycle_table(mat, pattern):
    n, m = len(mat), len(mat[0])
    r, c = len(pattern), len(pattern[0])

    def check(row, col, mask):
        for i in range(r):
            for j in range(c):
                if mat[row + i][col + j] != '?' and mat[row + i][col + j] != pattern[i][j] and (mask & (1 << (pattern[i][j].islower() or pattern[i][j] == '?'))):
                    return False
        return True

    def solve(q, stage_mask, h, b, dr, dc):
        if stage_mask == (1 << 26) - 1:
            return True

        mask = 1 << q

        if check(h, b, mask):
            for k in range(9):
                solve(k, stage_mask | (1 << k), h + dr[k], b + dc[k], dr, dc)

