            valid_cols = [mw*min(c, s) for mw, s in zip([m*n-r*2+1]*len(pattern), [r,c])]
            r_left, c_left = reduce(lambda x, y: (x[0] + y[0], x[1] + y[1]), valid_rows)
            w = (c_left - j)[0]
            s = (r_left - i)[0]
            if dfs(i,j, r_left, c_left, w+1, s+1, m, n):
                ans[i][j] = '1'
