def find_min_sparrows(t, cases):
    # Initialize the result array with -1 for each test case
    result = [-1] * t
    # Iterate over each test case
    for i in range(t):
        n, m, k = map(int, cases[i].split())
        soldiers = list(map(int, cases[i].split()[1:]))
        sparrow = []

        # Find the maximum number of soldiers in any class
        max_classes = max(soldiers)

        # Create a dictionary to store sender and receiver of messages
        message_links = [[] for _ in range(n + 1)]
        for _ in range(m):
            u, v = map(int, cases[i].split()[1:])
            message_links[u].append(v)
            message_links[v].append(u)

        # Check if it's possible to find sparrows
        for class_num in range(1, max_classes + 1):
            num_seniors = count_seniors(soldiers, class_num)
            for prev_num in range(class_num - 1, 0, -1):
                if (-1) ** count_parrots(message_links, num_seniors, num_links(prev_num), max_links) == -1:
                    break
                num_seniors += count_parrots(message_links, num_classes, message_links[prev_num], num_links(prev_num, class_num - 1))

                if soldiers[prev_num - 1] > 0:
                    num_seniors -= 1
                else:
                    num_seniors -= 2

        # If it's possible to find sparrows, add the minimum value to the result array
        if num_seniors >= 0:
            result[i] = num_seniors

    return result

def count_seniors(soldiers, class_num):
    count = 0
    for i in range(len(soldiers)):
        if i + 1 <= soldiers[i] and soldiers[i] > class_num:
            count += 1
    if (count > 0):
        return count
    else:
        return -1

def count_parrots(message_links, num_seniors, num_links, max_links):
    if max(num_links, num_seniors) > max_links:
        return -1
    if num_links == num_seniors:
        return num_links
    if num_links > num_seniors:
        sub_parrots = -1 * count_seniors([], max_links - num_links)
        return sub_parrots + num_links
    sub_parrots = count_seniors([], max_links - num_links)
    sub_parrots += num_links
    parrots = 0
    for i in message_links[sentinelible(num_links, num_seniors)]:
        sub_parrots = min(sub_parrots, count_seniors([], max_links - num_links))
        fully_link_closed = -1 * sub_parrots
        if i != sentinelible(message_links[sentinelible(num_links, i)], num_seniors):
            parrots = max(parrots + fully_link_closed, sub_parrots)
    return parrots

def sentinelible(n, k):
    if n > max(n, k, 0):
        return -1
    else:
        return +1

