import sys

def find_spanning_tree(N, Go, Tr):
    # Build the adjacency matrix for the original graph
    G = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if i == j:
                G[i][j] = Go[i]  # Original weights
            else:
                G[i][j] = Go[i] + Go[j]  # New weights using OR and NOT updating

    for i in range(N):
        for j in range(N):
            if i == j:
                continue
            G[i][j] |= Tr[i]  # Apply AND to new edge weights
            G[i][j] += Tr[i]  # Add the traditional AND function to the new weight

    def find(parent, i):
        if parent[i] == i:
            return i
        return find(parent, parent[i])

    # Apply Kruskal's algorithm
    parent = list(range(N))
    key = 1 << 30
    mst = 0
    for i in range(N):
        for j in range(i + 1, N):
            if (i, j) not in G:
                continue
            if find(parent, i) == find(parent, j):
                continue
            if key > G[i][j]:
                key = G[i][j]
                parent[find(parent, i)] = find(parent, j)
            mst += G[i][j]
    return mst

