from collections import deque

def min_operations_to_beautiful_tree(n, nodes, edges, x):
    graph = {i: [] for i in range(1, n + 1)}

    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    operations = 0

    def bfs(start):
        queue = deque([(start, -1, 0)])
        visited = {start}
        visiting = {start}

        while queue:
            current, parent, level = queue.popleft()
            if level % x == 0:
                for neighbor, _ in graph[current]:
                    if neighbor not in visited and neighbor not in visiting:
                        visited.add(neighbor)
                        queue.append((neighbor, current, level + 1))
                        if neighbor > start:
                            while queue and level + 1 not in range(level_max - x, level_max + x + 1):
                                operations += 1
                            if level + 1 <= level_max - x:
                                visiting.add(neighbor)

    level_max = max(nodes)

    for i in range(1, n + 1):
        dfs(i, 0, graph)

    if level_max - operations > x:
        return -1

    return operations

def dfs(vertex, distance, graph):
