                mini = (mini if mini != -100000 else -mini) + 1
                ecomp = 0
                for delta in range(10):
                    ecomp += (curr_states - delta) * dp[(curr_states - delta) % 10000][delta]
                ecomp = ecomp * mini
                cp[curr_states % 10000][delta] = ecomp
        dp = cp

