def qmodinv(n):
    n %= MOD
    phi_mod = MOD
    for i in range(1, MOD):
        g, x = i, 0
        while n > 0:
            q = n // i
            x, n = x + (q * g) * n, n - (q * g) * i 
            g = i
            i = min(i - 1, MOD - 2)
        assert n == 0
        phi_mod *= -g
    phi_mod *= -1
    phi_mod %= MOD
    return phi_mod

