mod = 1000000007

def count_satisfactory_arrays(n, m, b):
    # Initialize the DP array with zeros
    dp = [0] * (m + 1)
    dp[0] = 1  # Base case: 0 elements in the array

    for i in range(n):
        # Update the DP array with the number of arrays ending with each possible value
        for j in range(m, 0, -1):
            if j >= b[i]:
                dp[j] = (dp[j] + dp[j - b[i]]) % mod

    return sum(dp[1:m+1]) % mod

def main():
    n, m = map(int, input().split())
    b = list(map(int, input().split()))
    print(count_satisfactory_arrays(n, m, b))

if __name__ == "__main__":
    main()
